            /** @description Always false. A read now does not establish file content at a past action. */
            historical_content_verified: boolean;
            /** @description Creator-supplied link observed in the file; image bytes are not inspected. */
            image_uri?: string | null;
            /** Format: int32 */
            instruction_ordinal: number;
            /** Format: int64 */
            metadata_generation: number;
            /** Format: int64 */
            owner_generation: number;
            /** @description Always offchain_document_observation. */
